// Store holds users keyed by UserID.
type Store struct {
	users map[AccountID]User
}

// NewStore returns an empty Store.
func NewStore() *Store {
	return &Store{users: make(map[AccountID]User)}
}

// Get returns the user stored under id.
func (s *Store) Get(id AccountID) (User, bool) {
	u, ok := s.users[id]
	return u, ok
}

// Put stores u keyed by its ID.
func (s *Store) Put(u User) {
	s.users[u.ID] = u
}
